import{_ as p,c as r}from"./app.060934aa.js";const o={},e=r('<h1 id="\u6D4F\u89C8\u5668\u6E32\u67D3\u539F\u7406" tabindex="-1"><a class="header-anchor" href="#\u6D4F\u89C8\u5668\u6E32\u67D3\u539F\u7406" aria-hidden="true">#</a> \u6D4F\u89C8\u5668\u6E32\u67D3\u539F\u7406</h1><h2 id="_1-\u6D4F\u89C8\u5668\u5982\u4F55\u6E32\u67D3\u9875\u9762\u7684" tabindex="-1"><a class="header-anchor" href="#_1-\u6D4F\u89C8\u5668\u5982\u4F55\u6E32\u67D3\u9875\u9762\u7684" aria-hidden="true">#</a> 1.\u6D4F\u89C8\u5668\u5982\u4F55\u6E32\u67D3\u9875\u9762\u7684</h2><p>\u5F53\u6D4F\u89C8\u5668\u7684\u7F51\u7EDC\u7EBF\u7A0B\u6536\u5230 <code>HTML</code> \uFF0C\u4F1A\u4EA7\u751F\u4E00\u4E2A\u6E32\u67D3\u4EFB\u52A1\uFF0C\u5E76\u5C06\u5176\u4F20\u9012\u7ED9\u6E32\u67D3\u4E3B\u7EBF\u7A0B\u7684\u6D88\u606F\u961F\u5217\u3002\u5728\u4E8B\u4EF6\u5FAA\u73AF\u673A\u5236\u7684\u4F5C\u7528\u4E0B\uFF0C\u6E32\u67D3\u4E3B\u7EBF\u7A0B\u53D6\u51FA\u6D88\u606F\u961F\u5217\u4E2D\u7684\u6E32\u67D3\u4EFB\u52A1\uFF0C\u5F00\u542F\u6E32\u67D3\u6D41\u7A0B\u3002</p><hr><p>\u6574\u4E2A\u6E32\u67D3\u6D41\u7A0B\u5206\u4E3A\u591A\u4E2A\u9636\u6BB5\uFF0C\u5206\u522B\u662F\uFF1AHTML \u89E3\u6790\u3001\u6837\u5F0F\u8BA1\u7B97\u3001\u5E03\u5C40\u3001\u5206\u5C42\u3001\u7ED8\u5236\u3001\u5206\u5757\u3001\u5149\u6805\u5316\u3001\u753B\u3002\u6BCF\u4E2A\u9636\u6BB5\u90FD\u6709\u660E\u786E\u7684\u8F93\u5165\u8F93\u51FA\uFF0C\u4E0A\u4E00\u4E2A\u9636\u6BB5\u7684\u8F93\u51FA\u4F1A\u6210\u4E3A\u4E0B\u4E00\u4E2A\u9636\u6BB5\u7684\u8F93\u5165\u3002</p><hr><ol><li>\u6E32\u67D3\u7684\u7B2C\u4E00\u6B65\u89E3\u6790 <strong><code>HTML - Parse HTML</code></strong></li></ol><p>![[Drawing 2023-02-19 21.19.00.excalidraw.svg]]</p><p><strong>\u5F53HTML\u89E3\u6790\u8FC7\u7A0B\u4E2D\u9047\u5230CSS\u4EE3\u7801</strong></p><p>\u4E3A\u4E86\u63D0\u9AD8\u89E3\u6790\u6548\u7387\uFF0C\u6D4F\u89C8\u5668\u518D\u5F00\u59CB\u89E3\u6790\u524D\uFF0C\u4F1A\u542F\u52A8\u4E00\u4E2A\u9884\u89E3\u6790\u7684\u7EBF\u7A0B\uFF0C\u7387\u5148\u4E0B\u8F7D<code>HTML</code>\u4E2D\u7684\u5916\u90E8<code>CSS</code>\u6587\u4EF6\u548C<code>JS</code>\u6587\u4EF6</p><p>![[Drawing 2023-02-19 21.19.00.excalidraw 1.svg]]</p><p>\u5982\u679C\u4E3B\u7EBF\u7A0B\u89E3\u6790\u5230 <p color="#366168">link</p> \u4F4D\u7F6E\uFF0C\u6B64\u65F6\u5916\u90E8\u7684 <code>CSS</code> \u6587\u4EF6\u8FD8\u6CA1\u6709\u4E0B\u8F7D\u89E3\u6790\u597D\uFF0C\u4E3B\u7EBF\u7A0B\u4E0D\u4F1A\u7B49\u5F85\uFF0C\u7EE7\u7EED\u89E3\u6790\u540E\u7EED\u7684 <code>HTML</code>\u3002\u8FD9\u662F\u56E0\u4E3A\u4E0B\u8F7D\u548C\u89E3\u6790 <code>CSS</code> \u7684\u5DE5\u4F5C\u662F\u5728\u9884\u89E3\u6790\u7EBF\u7A0B\u4E2D\u8FDB\u884C\u7684\u3002\u8FD9\u5C31\u662F <code>CSS</code> \u4E0D\u4F1A\u963B\u585E <code>HTML</code> \u89E3\u6790\u7684\u6839\u672C\u539F\u56E0\u3002</p><p>![[null.png]]</p><p>\u5982\u679C\u4E3B\u7EBF\u7A0B\u89E3\u6790\u5230 <p color="#366168">script</p> \u4F4D\u7F6E\uFF0C\u4F1A\u505C\u6B62\u89E3\u6790HTML\uFF0C\u8F6C\u800C\u7B49\u5F85 <code>JS</code> \u6587\u4EF6\u4E0B\u8F7D\u597D\uFF0C\u5E76\u5C06\u5168\u5C40\u4EE3\u7801\u89E3\u6790\u6267\u884C\u5B8C\u6210\u540E\uFF0C\u624D\u7EE7\u7EED\u89E3\u6790HTML\u3002\u8FD9\u662F\u56E0\u4E3A JS \u4EE3\u7801\u7684\u6267\u884C\u8FC7\u7A0B\u53EF\u80FD\u4F1A\u4FEE\u6539\u5F53\u524D\u7684 DOM \u6811\uFF0C\u6240\u4EE5 DOM \u6811\u7684\u751F\u6210\u5FC5\u987B\u6682\u505C\u3002\u8FD9\u5C31\u662F JS \u4F1A\u963B\u585E HTML \u89E3\u6790\u7684\u6839\u672C\u539F\u56E0\u3002</p><p>\u7B2C\u4E00\u6B65\u5B8C\u6210\u540E\uFF0C\u4F1A\u5F97\u5230 DOM \u6811\u548C CSSOM \u6811\uFF0C\u6D4F\u89C8\u5668\u7684\u9ED8\u8BA4\u6837\u5F0F\u3001\u5185\u90E8\u6837\u5F0F\u3001\u5916\u90E8\u6837\u5F0F\u3001\u884C\u5185\u6837\u5F0F\u5747\u4F1A\u5305\u542B\u5728 CSSOM \u6811\u4E2D\u3002</p><hr><p>\u4E0B\u4E00\u6B65\u662F<strong>\u6837\u5F0F\u8BA1\u7B97</strong></p><p>\u4E3B\u7EBF\u7A0B\u4F1A\u904D\u5386\u5F97\u5230\u7684 DOM \u6811\uFF0C\u4F9D\u6B21\u4E3A\u6811\u4E2D\u7684\u6BCF\u4E2A\u8282\u70B9\u8BA1\u7B97\u51FA\u5B83\u6700\u7EC8\u7684\u6837\u5F0F\uFF0CComputed Style\uFF0C\u5F97\u5230\u4E00\u9897\u5E26\u6709\u6837\u5F0F\u7684 DOM \u6811\u3002</p><hr><p><strong>\u5E03\u5C40</strong></p><p>\u5E03\u5C40\u9636\u6BB5\u4F1A\u4F9D\u6B21\u904D\u5386 DOM \u6811\u7684\u6BCF\u4E00\u4E2A\u8282\u70B9\uFF0C\u8BA1\u7B97\u6BCF\u4E2A\u8282\u70B9\u7684\u51E0\u4F55\u4FE1\u606F\u3002\u4F8B\u5982\u8282\u70B9\u7684\u5BBD\u9AD8\u3001\u76F8\u5BF9\u5305\u542B\u5757\u7684\u4F4D\u7F6E\u3002</p><p>\u4F8B\u5982\uFF1Adisplay\uFF1Anone\u7684\u8282\u70B9\u6CA1\u6709\u51E0\u4F55\u4FE1\u606F\uFF0C\u4E0D\u4F1A\u751F\u6210\u5230\u5E03\u5C40\u6811\uFF1B\u4F2A\u5143\u7D20\u9009\u62E9\u5668\uFF0CDOM\u6811\u4E2D\u4E0D\u5B58\u5728\u8FD9\u4E9B\u4F2A\u5143\u7D20\u8282\u70B9\uFF0C\u4F46\u62E5\u6709\u51E0\u4F55\u4FE1\u606F\uFF0C\u4F1A\u751F\u6210\u5230\u5E03\u5C40\u6811\u4E2D\u3002\u533F\u540D\u884C\u76D2\u3001\u533F\u540D\u5757\u76D2\u7B49\u90FD\u4F1A\u5BFC\u81F4 DOM \u6811\u548C\u5E03\u5C40\u6811\u65E0\u6CD5\u4E00\u4E00\u5BF9\u5E94</p><hr><p><strong>\u5206\u5C42</strong></p><p>\u4E3B\u7EBF\u7A0B\u5C06\u6574\u4E2A\u5E03\u5C40\u6811\u8FDB\u884C\u5206\u5C42\u3002\u4F7F\u5F97\u5C06\u6765\u67D0\u4E00\u4E2A\u5C42\u6539\u53D8\u540E\uFF0C\u4EC5\u4F1A\u5BF9\u6539\u5C42\u8FDB\u884C\u540E\u7EED\u5904\u7406\uFF0C\u4ECE\u800C\u63D0\u5347\u6548\u7387\u3002\u6EDA\u52A8\u6761\u3001\u5806\u53E0\u4E0A\u4E0B\u6587\u3001transform\u3001opacity\u7B49\u6837\u5F0F\u6216\u5BF9\u6216\u5C11\u7684\u5F71\u54CD\u5206\u5C42\u7ED3\u679C\uFF0C\u53EF\u4EE5\u4F7F\u7528will-change\u5C5E\u6027\uFF0C\u5C06\u9875\u9762\u5143\u7D20\u5206\u5C42\uFF0C\u4ECE\u800C\u4F18\u5316\u6E32\u67D3\u6548\u7387\u3002</p><hr><p><strong>\u7ED8\u5236</strong></p><p>\u4E3B\u7EBF\u7A0B\u4F1A\u4E3A\u6BCF\u4E2A\u5C42\u5355\u72EC\u4EA7\u751F\u7ED8\u5236\u6307\u4EE4\u96C6\uFF0C\u7528\u4E8E\u63CF\u8FF0\u8FD9\u4E00\u5C42\u7684\u5185\u5BB9\u8BE5\u5982\u4F55\u753B\u51FA\u3002</p><hr><p>\u5B8C\u6210\u7ED8\u5236\u540E\uFF0C\u4E3B\u7EBF\u7A0B\u5C06\u6BCF\u4E2A\u56FE\u5C42\u7684\u7ED8\u5236\u4FE1\u606F\u4EA4\u7ED9\u5408\u6210\u7EBF\u7A0B\uFF0C\u5269\u4F59\u5DE5\u4F5C\u5C06\u7531\u5408\u6210\u7EBF\u7A0B\u5B8C\u6210\u3002</p><p>\u5408\u6210\u7EBF\u7A0B\u9996\u5148\u5BF9 \u6BCF\u4E2A\u56FE\u5C42\u8FDB\u884C\u5206\u5757\uFF0C\u5C06\u5176\u5212\u5206\u4E3A\u66F4\u591A\u7684\u5C0F\u533A\u57DF\u3002</p><p>\u5B83\u4F1A\u4ECE\u7EBF\u7A0B\u6C60\u4E2D\u62FF\u53D6\u591A\u4E2A\u7EBF\u7A0B\u6765\u5B8C\u6210\u5206\u5757\u5DE5\u4F5C\u3002</p><hr><p>\u5206\u5757\u5B8C\u6210\u540E\uFF0C\u8FDB\u5165<strong>\u5149\u6805\u5316</strong>\u9636\u6BB5\u3002 \u5408\u6210\u7EBF\u7A0B\u4F1A\u5C06\u5FEB\u4FE1\u606F\u7ED9 GPU \u8FDB\u7A0B\uFF0C\u4EE5\u6781\u9AD8\u7684\u901F\u5EA6\u5B8C\u6210\u5149\u6805\u5316\u3002 GPU \u8FDB\u7A0B\u4F1A\u5F00\u542F\u591A\u4E2A\u7EBF\u7A0B\u6765\u5B8C\u6210\u5149\u6805\u5316\uFF0C\u5E76\u4E14\u4F18\u5148\u5904\u7406\u9760\u8FD1\u89C6\u53E3\u533A\u57DF\u7684\u5757\u3002 \u5149\u6805\u5316\u7684\u7ED3\u679C\uFF0C\u5C31\u662F\u4E00\u5757\u4E00\u5757\u7684\u4F4D\u56FE</p><hr><p><strong>\u753B</strong></p><p>\u5408\u6210\u7EBF\u7A0B\u62FF\u5230\u6BCF\u4E2A\u5C42\u3001\u6BCF\u4E2A\u5757\u7684\u4F4D\u56FE\u540E\uFF0C\u751F\u6210\u4E00\u4E2A\u4E2A\uFF08\u6307\u5F15quad\uFF09\u4FE1\u606F\u3002 \u6307\u5F15\u4F1A\u6807\u8BC6\u51FA\u6BCF\u4E2A\u4F4D\u56FE\u5E94\u8BE5\u753B\u5230\u5C4F\u5E55\u7684\u90A3\u4E2A\u4F4D\u7F6E\uFF0C\u4EE5\u53CA\u4F1A\u8003\u8651\u5230\u65CB\u8F6C\u3001\u7F29\u653E\u3002 \u53D8\u5F62\u53D1\u751F\u5728\u5408\u6210\u7EBF\u7A0B\uFF0C\u4E0E\u6E32\u67D3\u4E3B\u7EBF\u7A0B\u65E0\u5173\uFF0C\u8FD9\u662F transform \u6548\u7387\u9AD8\u7684\u672C\u8D28\u539F\u56E0\u3002 \u5408\u6210\u7EBF\u7A0B\u628A quad \u63D0\u4EA4\u7ED9 GPU \u8FDB\u7A0B\uFF0C\u6709 GPU \u8FDB\u7A0B\u4EA7\u751F\u7CFB\u7EDF\u8C03\u7528\uFF0C\u63D0\u4EA4\u7ED9 GPU \u786C\u4EF6\uFF0C\u5B8C\u6210\u6210\u50CF\u3002</p><hr><p><strong>reflow</strong></p><p>\u672C\u8D28\u662F\u91CD\u65B0\u8BA1\u7B97 layout \u6811\u3002 \u5F53\u8FDB\u884C\u4E86\u4F1A\u5F71\u54CD\u5E03\u5C40\u6811\u7684\u64CD\u4F5C\u540E\uFF0C\u9700\u8981\u91CD\u65B0\u8BA1\u7B97\u5E03\u5C40\u6811\uFF0C\u4F1A\u5F15\u53D1 layout\u3002 \u4E3A\u4E86\u907F\u514D\u8FDE\u7EED\u7684\u591A\u6B21\u64CD\u4F5C\u5BFC\u81F4\u5E03\u5C40\u6811\u53CD\u590D\u8BA1\u7B97\uFF0C\u6D4F\u89C8\u5668\u4F1A\u5408\u5E76\u8FD9\u4E9B\u64CD\u4F5C\uFF0C\u5F53 JS \u4EE3\u7801\u5168\u90E8\u5B8C\u6210\u540E\u5728\u8FDB\u884C\u7EDF\u4E00\u8BA1\u7B97\u3002\u6240\u4EE5\uFF0C\u6539\u52A8\u5C5E\u6027\u9020\u6210\u7684reflow\u662F\u5F02\u6B65\u5B8C\u6210\u7684\u3002 \u56E0\u4E3A\u5982\u6B64\uFF0C\u5F53 JS \u83B7\u53D6\u5E03\u5C40\u5C5E\u6027\u65F6\uFF0C\u5C31\u53EF\u80FD\u9020\u6210\u65E0\u6CD5\u83B7\u53D6\u5230\u6700\u65B0\u7684\u5E03\u5C40\u4FE1\u606F\u3002 \u6700\u7EC8\u51B3\u5B9A\u83B7\u53D6\u5C5E\u6027\u7ACB\u5373 reflow\u3002 ![[Pasted image 20230305185305.png]]</p><hr><p><strong>repaint\u91CD\u7ED8</strong></p><p>\u672C\u8D28\u662F\u6839\u636E\u5206\u5C42\u4FE1\u606F\u8BA1\u7B97\u4E86\u7ED8\u5236\u6307\u4EE4\u3002 \u5F53\u6539\u52A8\u4E86\u53EF\u89C1\u6837\u5F0F\u540E\uFF0C\u9700\u8981\u91CD\u65B0\u8BA1\u7B97\uFF0C\u4F1A\u5F15\u53D1 repaint\u3002 \u7531\u4E8E\u5143\u7D20\u7684\u5E03\u5C40\u4FE1\u606F\u4E5F\u5C5E\u4E8E\u53EF\u89C1\u6837\u5F0F\uFF0C\u6240\u4EE5 reflow \u4E00\u5B9A\u4F1A\u5F15\u8D77 repaint\u3002</p><hr>',44);function t(n,a){return e}var d=p(o,[["render",t],["__file","\u6D4F\u89C8\u5668\u6E32\u67D3\u539F\u7406.html.vue"]]);export{d as default};
